UPDATE categories child SET parent_id = parent.id
FROM parents relation JOIN categories parent ON parent.code = relation.parent_code
WHERE child.code = relation.child_code;

UPDATE categories SET parent_id = (SELECT id FROM categories WHERE code = 'market-agriculture')
WHERE parent_id IS NULL AND code NOT LIKE 'market-%';
UPDATE categories SET image_index = 17 WHERE code NOT LIKE 'market-%';
